let webhookItems = [];

// Safely check which trigger node executed to grab the original payload
if ($('1Rotary AiraFace IN').isExecuted) {
  webhookItems = $('1Rotary AiraFace IN').all();
} else if ($('Face Detection').isExecuted) {
  webhookItems = $('Face Detection').all();
}

// If neither trigger has data, safely pass the input through to avoid crashing
if (!webhookItems || webhookItems.length === 0) {
  return $input.all();
}

const dbItems = $input.all();
const outputItems = [];

for (let i = 0; i < webhookItems.length; i++) {
  // Create a deep COPY of the item to bypass n8n's read-only restriction
  const newItem = JSON.parse(JSON.stringify(webhookItems[i]));

  const body = newItem.json.body;
  if (!body) {
    outputItems.push(newItem);
    continue;
  }

  // Extract Role (Handles array or string depending on payload)
  newItem.json.extractedRole = Array.isArray(body.role) 
    ? body.role.find(r => r === 'Day Employee') || null 
    : (typeof body.role === 'string' ? body.role : null);

  // Convert Time and Calculate Status
  if (body.time) {
    // Safely parse the time string
    const timeStr = body.time.includes('/') ? body.time.replace(/\//g, '-') : body.time;
    const isoString = timeStr.replace(' ', 'T') + '+08:00';
    let checkInDate = new Date(isoString);

    // Fallback if parsing fails
    if (isNaN(checkInDate.getTime())) checkInDate = new Date();

    newItem.json.epochTime = checkInDate.getTime();

    // --- Dynamic Shift Start from Employee_Events ---
    const dbRow = dbItems[i]?.json || {};
    const shiftStartStr = dbRow.shift_start || "08:00"; 

    const [shiftHours, shiftMinutes] = shiftStartStr.split(':').map(Number);

    const shiftStart = new Date(newItem.json.epochTime);
    shiftStart.setHours(shiftHours || 8, shiftMinutes || 0, 0, 0);

    const gracePeriodEnd = new Date(shiftStart);
    gracePeriodEnd.setMinutes(gracePeriodEnd.getMinutes() + 15);

    // Evaluate Status and Assign Email Colors
    if (newItem.json.epochTime < shiftStart.getTime()) {
        newItem.json.arrivalStatus = "Early";
        newItem.json.statusColorText = "#0284c7"; 
        newItem.json.statusColorBg = "#e0f2fe";   
    } else if (newItem.json.epochTime <= gracePeriodEnd.getTime()) {
        newItem.json.arrivalStatus = "On Time";
        newItem.json.statusColorText = "#10b981"; 
        newItem.json.statusColorBg = "#ecfdf5";   
    } else {
        newItem.json.arrivalStatus = "Late";
        newItem.json.statusColorText = "#ef4444"; 
        newItem.json.statusColorBg = "#fef2f2";   
    }
  } else {
    newItem.json.epochTime = null;
    newItem.json.arrivalStatus = "Unknown";
    newItem.json.statusColorText = "#64748b";
    newItem.json.statusColorBg = "#f1f5f9";
  }

  // Push the successfully modified copy
  outputItems.push(newItem);
}

return outputItems;

const rotaryData = $('Get 1Rotary').all();
const eventData = $('Get Employee_Events').all();

// 1. Build a master dictionary including shift data
const employeeMap = new Map();

// Process Employee_Events (Master Schedule)
if (eventData && eventData.length > 0) {
    for (const item of eventData) {
        // Skip the empty fallback item if the database was empty
        if (!item.json || Object.keys(item.json).length === 0) continue; 

        const pid = item.json.person_id;
        if (!pid) continue;

        // Parse complex fields
        let days = item.json.assigned_days;
        if (typeof days === 'string') {
            try { days = JSON.parse(days); } catch(e) { days = []; }
        }

        employeeMap.set(pid, {
            id: pid,
            person_id: pid, // Explicitly pass person_id for the frontend
            name: item.json.name || "Unknown",
            role: item.json.role || "Cleaner",
            assigned_days: days || [], // Use snake_case to match frontend
            shift_start: item.json.shift_start || "08:00", 
            status: "Absent",
            lastCheckIn: null,
            camera: null,
            faceImage: null
        });
    }
}

// 2. Overlay live telemetry from 1Rotary
if (rotaryData && rotaryData.length > 0) {
    for (const item of rotaryData) {
        // Skip the empty fallback item if the database was empty
        if (!item.json || Object.keys(item.json).length === 0) continue;

        const pid = item.json.person_id;
        if (!pid) continue;

        if (!employeeMap.has(pid)) {
            employeeMap.set(pid, {
                id: pid,
                person_id: pid,
                name: item.json.name || "Unknown",
                role: item.json.role || "Cleaner",
                assigned_days: [],
                shift_start: "08:00", 
                status: "Present",
                lastCheckIn: item.json.time,
                camera: item.json.camera,
                faceImage: item.json.face_image
            });
            continue;
        }

        const emp = employeeMap.get(pid);
        emp.status = "Present";
        emp.lastCheckIn = item.json.time;
        if (item.json.face_image) emp.faceImage = item.json.face_image;
        emp.camera = item.json.camera;
    }
}

return Array.from(employeeMap.values()).map(emp => ({ json: emp }));

